def is_nested(string):
    open_count = 0
    second_open_index = None

    for i, ch in enumerate(string):
        if ch == '[':
            open_count += 1
            if open_count == 2:
                second_open_index = i
                break

    if second_open_index is None:
        return False

    # Need at least two closing brackets after the second opening bracket
    return string[second_open_index + 1:].count(']') >= 2

