def bf(planet1, planet2):
    """
    Returns a tuple of all planets whose orbits lie between the orbits of
    planet1 and planet2, sorted by proximity to the Sun.

    The function returns an empty tuple if either planet name is invalid.
    """
    planets = [
        "Mercury", "Venus", "Earth", "Mars",
        "Jupiter", "Saturn", "Uranus", "Neptune"
    ]

    if planet1 not in planets or planet2 not in planets:
        return ()

    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)

    start = min(idx1, idx2) + 1
    end = max(idx1, idx2)

    return tuple(planets[start:end])
